actions.script:
const devices = ec.resource.script('component://moqui-device/service/moqui/device/Devices.js')
try {
    for (const destination of destinations) {
        transferredFiles = transferredFiles.concat(devices.execute('transferFiles',
            {endpoint:destination.endpoint, options:destination.options, files:rendered.files}).transferredFiles)
    }
    status = 'completed'
} catch (error) {
    status = 'failed'
    errorMessage = String(error && error.message ? error.message : error)
}

service-call.in-map:
{eventType:(status === 'completed' ? 'exportCompleted' : 'writeFailed'), requestName:requestName,
                        status:status, protocol:'Device Config Export', routeId:'run-device-config-export', rowCount:rowCount,
                        message:(status === 'completed' ? ('Device configuration export completed for rule set ' + deviceRuleSetId + '.') : errorMessage)}
